fn bmat(
    top_left: Vec<f32>,
    top_right: Vec<f32>,
    bottom_left: Vec<f32>,
    bottom_right: Vec<f32>,
) -> Vec<f32> {
    let n = top_left.len();
    // If you want to ensure the inputs all have the same length in debug builds:
    debug_assert_eq!(top_right.len(), n);
    debug_assert_eq!(bottom_left.len(), n);
    debug_assert_eq!(bottom_right.len(), n);

    // Reserve exactly 4n slots so we don't have to reallocate.
    let mut result = Vec::with_capacity(4 * n);
    result.extend(top_left);
    result.extend(top_right);
    result.extend(bottom_left);
    result.extend(bottom_right);
    result
}

